(async () => {
  const suffix = Math.random().toString(36).slice(2, 7);
  console.log('— auth —');
  const a = await call('/register', { body: { username: 'alice_' + suffix, password: 'test1234' } });
  ok('register alice', a.status === 200 && a.data.user.glimmers === 250);
  const b = await call('/register', { body: { username: 'bob_' + suffix, password: 'test1234' } });
  ok('register bob', b.status === 200);
  const dup = await call('/register', { body: { username: 'alice_' + suffix, password: 'x1234' } });
  ok('duplicate username rejected', dup.status === 409);
  const badLogin = await call('/login', { body: { username: 'alice_' + suffix, password: 'wrong' } });
  ok('bad password rejected', badLogin.status === 401);
  const ca = a.cookie, cb = b.cookie;

  console.log('— games & catalog —');
  const games = (await call('/games', {}, ca)).data.games;
  ok('4 official games listed', games.filter((g) => g.official).length === 4);
  const obby = games.find((g) => g.name === 'Tower of Bother');
  const buy = await call('/catalog/hat_traffic/buy', { method: 'POST', body: {} }, ca);
  ok('buy hat (250-30=220)', buy.status === 200 && buy.data.glimmers === 220);
  const buy2 = await call('/catalog/hat_traffic/buy', { method: 'POST', body: {} }, ca);
  ok('double-buy rejected', buy2.status === 400);
  const broke = await call('/catalog/hat_crown/buy', { method: 'POST', body: {} }, ca);
  ok('cannot afford crown(500)', broke.status === 400);
  const av = await call('/avatar', { body: { hat: 'hat_traffic', bodyColors: { torso: '#e54b4b' } } }, ca);
  ok('equip hat + recolor', av.status === 200 && av.data.avatar.hat === 'hat_traffic' && av.data.avatar.bodyColors.torso === '#e54b4b');
  const avBad = await call('/avatar', { body: { hat: 'hat_crown' } }, ca);
  ok('cannot equip unowned hat', avBad.status === 400);

  console.log('— friends —');
  const fr = await call('/friends/request', { body: { username: 'bob_' + suffix } }, ca);
  ok('friend request sent', fr.status === 200);
  const frlist = await call('/friends', {}, cb);
  ok('bob sees request', frlist.data.requests.length === 1);
  await call('/friends/respond', { body: { userId: frlist.data.requests[0].id, accept: true } }, cb);
  const fl2 = await call('/friends', {}, ca);
  ok('now friends', fl2.data.friends.length === 1);

  console.log('— multiplayer lobby (real WS) —');
  const wsA = await wsConnect(ca);
  wsA.send(JSON.stringify({ t: 'join', gameId: obby.id }));
  const joinedA = await expect(wsA, 'joined');
  ok('alice joined lobby, world has parts', joinedA.world.parts.length === 67);
  ok('config delivered', joinedA.config.mode === 'obby' && joinedA.config.maxPlayers === 16);

  const wsB = await wsConnect(cb);
  wsB.send(JSON.stringify({ t: 'join', gameId: obby.id }));
  const joinedB = await expect(wsB, 'joined');
  ok('bob joined same instance', joinedB.instanceId === joinedA.instanceId);
  ok('bob sees alice in player list', joinedB.players.some((p) => p.username === 'alice_' + suffix));
  const pjoin = await expect(wsA, 'pjoin');
  ok('alice notified of bob joining', pjoin.player.username === 'bob_' + suffix);

  wsA.send(JSON.stringify({ t: 'move', p: [1, 2, 3], yaw: 0.5, anim: 'walk' }));
  const pmove = await expect(wsB, 'p');
  ok('movement relayed to bob', pmove.p[0] === 1 && pmove.p[2] === 3 && pmove.anim === 'walk');

  wsA.send(JSON.stringify({ t: 'chat', text: 'hello bob!' }));
  let chat = await expect(wsB, 'chat');
  while (chat.system) chat = await expect(wsB, 'chat');
  ok('chat relayed', chat.text === 'hello bob!' && chat.username === 'alice_' + suffix);

  // coin: find a coin part, move next to it, touch
  const coin = joinedA.world.parts.find((p) => p.type === 'coin');
  wsA.send(JSON.stringify({ t: 'move', p: [coin.x, coin.y, coin.z], yaw: 0, anim: 'idle' }));
  await new Promise((r) => setTimeout(r, 100));
  wsA.send(JSON.stringify({ t: 'touch', partId: coin.id }));
  const coinMsg = await expect(wsB, 'coin');
  ok('server-validated coin pickup broadcast', coinMsg.partId === coin.id);

  // cheat attempt: touch far-away goal
  const goal = joinedA.world.parts.find((p) => p.type === 'goal');
  wsA.send(JSON.stringify({ t: 'move', p: [0, 2, 0], yaw: 0, anim: 'idle' }));
  await new Promise((r) => setTimeout(r, 100));
  wsA.send(JSON.stringify({ t: 'touch', partId: goal.id }));
  let cheated = false;
  try { await expect(wsB, 'goalhit', 700); cheated = true; } catch (e) {}
  ok('far-away goal touch rejected (anti-cheat)', !cheated);

  wsA.send(JSON.stringify({ t: 'stage', n: 2 }));
  const lb = await expect(wsB, 'lb');
  ok('leaderboard broadcast on checkpoint', lb.entries.some((e) => e.stage === 2));

  console.log('— game creation + studio collab —');
  const created = await call('/games', { body: { name: 'Test World' } }, ca);
  ok('alice creates place', created.status === 200 && created.data.game.partCount === 2);
  const gid = created.data.game.id;
  const privCheck = await call('/games/' + gid, {}, cb);
  ok('private place blocked for bob', privCheck.status === 403);
  await call(`/games/${gid}/collaborators`, { body: { username: 'bob_' + suffix, action: 'add' } }, ca);
  const privCheck2 = await call('/games/' + gid, {}, cb);
  ok('collaborator can view', privCheck2.status === 200);

  const stA = await wsConnect(ca);
  stA.send(JSON.stringify({ t: 'studio', gameId: gid }));
  const sjA = await expect(stA, 'sjoined');
  ok('alice in studio, owner', sjA.isOwner === true);
  const stB = await wsConnect(cb);
  stB.send(JSON.stringify({ t: 'studio', gameId: gid }));
  const sjB = await expect(stB, 'sjoined');
  ok('bob co-edits (collaborator)', sjB.isOwner === false && sjB.world.parts.length === 2);
  await expect(stA, 'sjoin');

  stA.send(JSON.stringify({ t: 'op', op: { kind: 'add', part: { id: 'newpart1', type: 'kill', x: 5, y: 1, z: 5, sx: 4, sy: 1, sz: 4, color: '#d40000' } } }));
  const opB = await expect(stB, 'op');
  ok('live op sync: bob sees alice add part', opB.op.kind === 'add' && opB.op.part.type === 'kill');
  stB.send(JSON.stringify({ t: 'op', op: { kind: 'update', part: { ...opB.op.part, x: 10 } } }));
  const opA = await expect(stA, 'op');
  ok('live op sync: alice sees bob move it', opA.op.part.x === 10);
  stB.send(JSON.stringify({ t: 'sel', partId: 'newpart1' }));
  const selA = await expect(stA, 'sel');
  ok('selection presence synced', selA.partId === 'newpart1');
  stA.send(JSON.stringify({ t: 'op', op: { kind: 'meta', data: { name: 'Renamed World', public: true, config: { mode: 'obby', gravity: 60 } } } }));
  const metaB = await expect(stB, 'op');
  ok('config sync', metaB.op.data.name === 'Renamed World' && metaB.op.data.config.gravity === 60);

  // persistence check
  const after = await call('/games/' + gid, {}, cb);
  ok('ops persisted (3 parts, renamed, public)', after.data.game.partCount === 3 && after.data.game.name === 'Renamed World' && after.data.game.public === true);

  // unauthorized studio access
  const c = await call('/register', { body: { username: 'eve_' + suffix, password: 'test1234' } });
  const stC = await wsConnect(c.cookie);
  stC.send(JSON.stringify({ t: 'studio', gameId: gid }));
  const errC = await expect(stC, 'error');
  ok('non-collaborator denied studio', /access/i.test(errC.error));

  console.log('— misc —');
  const thumb = await fetch(`${BASE}/api/games/${obby.id}/thumb.svg`);
  ok('thumbnail SVG renders', thumb.status === 200 && (await thumb.text()).includes('<svg'));
  const prof = await call('/users/alice_' + suffix, {}, cb);
  ok('profile lists public game', prof.data.games.some((g) => g.name === 'Renamed World'));
  const presence = await call('/friends', {}, cb);
  ok('presence: alice shown in-game/online', presence.data.friends[0].online === true);

  [wsA, wsB, stA, stB, stC].forEach((w) => w.close());
  console.log(`\n${pass} passed, ${fail} failed`);
  process.exit(fail ? 1 : 0);
})().catch((e) => { console.error('TEST CRASH:', e); process.exit(1); });
